"""Generate the authorised MP3/WAV native-media fixture with official Anki."""
from math import pi, sin
from pathlib import Path
from struct import pack
from tempfile import TemporaryDirectory
from wave import open as wave_open

from anki.collection import Collection, DeckIdLimit, ExportAnkiPackageOptions


OUT = Path("e2e/fixtures/native-media.apkg")
# Synthetic C5 tone generated byte-for-byte with FFmpeg 7.1.1:
# ffmpeg -hide_banner -loglevel error -f lavfi \
#   -i 'sine=frequency=523.25:duration=1.5' -ar 8000 -ac 1 -b:a 24k \
#   e2e/fixtures/native-tone.mp3
MP3 = Path("e2e/fixtures/native-tone.mp3").read_bytes()


def write_wav(path: Path) -> None:
    rate = 8_000
    frames = b"".join(pack("<h", int(7_500 * sin(2 * pi * 440 * index / rate))) for index in range(rate * 3))
    with wave_open(str(path), "wb") as output:
        output.setnchannels(1)
        output.setsampwidth(2)
        output.setframerate(rate)
        output.writeframes(frames)


with TemporaryDirectory() as temporary:
    root = Path(temporary)
    collection = Collection(str(root / "collection.anki2"))
    deck_id = collection.decks.id("HoloRecall Native Media")
    mp3_path = root / "native-tone.mp3"
    wav_path = root / "native-tone.wav"
    mp3_path.write_bytes(MP3)
    write_wav(wav_path)
    mp3_name = collection.media.add_file(str(mp3_path))
    wav_name = collection.media.add_file(str(wav_path))

    model = collection.models.new("HoloRecall Native Media")
    for field_name in ("Prompt", "Answer", "Sound"):
        collection.models.add_field(model, collection.models.new_field(field_name))
    template = collection.models.new_template("Forward")
    template["qfmt"] = "{{Prompt}}<br>{{Sound}}"
    template["afmt"] = "{{FrontSide}}<hr>{{Answer}}"
    collection.models.add_template(model, template)
    collection.models.add(model)

    for prompt, answer, media_name, tags in (
        ("Play the imported MP3 tone", "MP3 media answer", mp3_name, ["native-media", "mp3"]),
        ("Play the imported WAV tone", "WAV media answer", wav_name, ["native-media", "wav"]),
    ):
        note = collection.new_note(model)
        note["Prompt"] = prompt
        note["Answer"] = answer
        note["Sound"] = f"[sound:{media_name}]"
        note.tags = tags
        collection.add_note(note, deck_id)

    OUT.parent.mkdir(parents=True, exist_ok=True)
    collection.export_anki_package(
        out_path=str(OUT),
        options=ExportAnkiPackageOptions(
            with_scheduling=False,
            with_deck_configs=False,
            with_media=True,
            legacy=True,
        ),
        limit=DeckIdLimit(deck_id=deck_id),
    )
    collection.close()
